X = [[40, 1], [60, 2], [80, 2], [100, 3], [120, 3], [140, 4]]
y = [70, 105, 135, 170, 200, 235]

def entrenar(X, y):
    return sum(y) / len(y)          # el baseline predice siempre la media

def predecir(modelo, X):
    return [modelo for _ in X]

def mse(real, predicho):
    return sum((r - p) ** 2 for r, p in zip(real, predicho)) / len(real)

modelo = entrenar(X, y)
predicciones = predecir(modelo, X)

print("predicción constante:", modelo)
print("MSE:", round(mse(y, predicciones), 2))
